namespace BancoBrasil;
require_once APPPATH.'services/CompanyReceiptReversalSource.php';
require_once APPPATH.'services/CompanyBankReversalData.php';
require_once APPPATH.'services/CompanyBankReceiptReversals.php';
require_once APPPATH.'services/CompanyInvoiceBalance.php';
require_once __DIR__.'/Reconciliation.php';
require_once __DIR__.'/ApiMovements.php';
/** Recording an externally completed full reversal declared by an operator; never bank authentication/execution. */
final class ReviewedExternalReversal implements \CompanyReceiptReversalSource
{
    private array $balanceTables=[];
    private bool $hasAsaas=false;
