        ReconciliationSchema::ensure($db,$p,false);OriginationSchema::assertValid($db,$p);\CompanyBankComponentsSchema::assertValid($db,$p);\CompanyBankReversalSchema::assertValid($db,$p);
        require_once __DIR__.'/ApiWebhookSchema.php';ApiWebhookSchema::ensure($db,$p,false);$this->balanceTables=(new \CompanyInvoiceBalance($db,$p))->tables();$this->hasAsaas=$db->table_exists($p.'asaas_payment_origins');
    }
    public function tables():array{return array_values(array_unique(array_merge(Reconciliation::tables(),$this->balanceTables,['bb_api_receipts','bb_api_operations','bb_api_notifications','bb_api_webhook_receivers','company_bank_receipt_reversals','company_currency_units','company_financial_events','invoicepaymentrecords','company_payment_receipts','invoices','issuers_invoice_documents','issuers_audit'],$this->hasAsaas?['asaas_payment_origins']:[])));}
    public function claim($db,string $p,int $issuer,int $actor):array
    {
        \IssuerTransaction::assertOwned($db,$p,$this->tables());$acl=new \IssuerResourceAccess($db,$p);$acl->lockFinancialIdentity($issuer,$actor);\IssuerStorage::query($db,'SELECT module_name FROM '.$p.'modules WHERE module_name=? FOR UPDATE',['banco_brasil']);Reconciliation::authorize($db,$p,$issuer,$actor,'reconcile');Reconciliation::authorize($db,$p,$issuer,$actor,'external_reverse');if(!$acl->can($issuer,$actor,'payments','delete')||!$acl->can($issuer,$actor,'invoices','view'))throw new \DomainException('bb_external_reversal_access_denied');
        $records=\IssuerStorage::query($db,"SELECT r.*,p.invoiceid,p.date,p.amount FROM {$p}bb_event_receipts r JOIN {$p}invoicepaymentrecords p ON p.id=r.payment_id JOIN {$p}invoices i ON i.id=p.invoiceid AND i.issuer_id=r.issuer_id JOIN {$p}issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id WHERE r.payment_id=? AND r.issuer_id=? FOR UPDATE",[$this->paymentId,$issuer])->result_array();if(count($records)!==1)throw new \DomainException('bb_external_reversal_original_unavailable');$receipt=$records[0];$invoice=(int)$receipt['invoiceid'];$eventId=(int)$receipt['event_id'];
        $all=(new \CompanyBankReceiptComponents($db,$p))->forInvoiceInOwned($issuer,$actor,$invoice);if(!isset($all[$this->paymentId]))throw new \DomainException('bb_external_reversal_components_required');$original=\CompanyBankComponentsData::fromCaptured($all[$this->paymentId]);$data=$original->data();if(!hash_equals($receipt['evidence_hash'],$data['evidence_hash']))throw new \DomainException('bb_external_reversal_original_corrupt');
        [$row,$event]=Reconciliation::event($db,$p,$issuer,$eventId);[$origin,$snapshot,$batch]=Reconciliation::origin($db,$p,$issuer,$row,$event);if((int)$origin['id']!==(int)$receipt['origin_id']||(int)$origin['invoice_id']!==$invoice)throw new \DomainException('bb_external_reversal_original_corrupt');
        $link=\IssuerStorage::query($db,"SELECT origin_id FROM {$p}bb_event_links WHERE event_id=? AND issuer_id=? FOR UPDATE",[$eventId,$issuer])->row_array();if(!$link||(int)$link['origin_id']!==(int)$origin['id']||($event['channel']??null)!=='cnab240'||($event['layout']??null)!==Agreement::LAYOUT_ID||$row['occurrence']!=='06'||$row['observation']!=='settlement_reported'||($event['currency']??null)!=='BRL'||$batch['generation_state']!=='generated'||$batch['delivery_state']!=='reported_submitted'||$batch['layout_id']!==Agreement::LAYOUT_ID||$batch['layout_source_hash']!==Agreement::SOURCE_SHA256||$receipt['date']!==($event['credit_date']??null))throw new \DomainException('bb_external_reversal_original_corrupt');
        $proof=false;foreach(\IssuerStorage::query($db,"SELECT reason,evidence_reference FROM {$p}bb_event_reviews WHERE event_id=? AND issuer_id=? AND actor_id=? AND decision='components_credit_confirmed' FOR UPDATE",[$eventId,$issuer,$receipt['created_by']])->result_array() as $review){$hash=hash('sha256',json_encode([$row['payload_hash'],$origin['payload_hash'],$review['evidence_reference'],$review['reason'],\CompanyBankComponentsData::BASIS],JSON_THROW_ON_ERROR));if(hash_equals($data['evidence_hash'],$hash))$proof=true;}if(!$proof)throw new \DomainException('bb_external_reversal_original_corrupt');
        $reconstructed=\CompanyBankComponentsData::fromCnab240($event,$snapshot['title']['amount'],$data['balance_before'],$data['evidence_hash']);if(!hash_equals($original->fingerprint(),$reconstructed->fingerprint()))throw new \DomainException('bb_external_reversal_original_corrupt');
        // The new declaration grants no exception to the old adverse/source/ownership vetoes.
        $adverse=\IssuerStorage::query($db,"SELECT id FROM {$p}bb_return_events WHERE issuer_id=? AND scope_key=? AND remote_id=? AND control_reference=? AND id<>? AND (occurrence IN ('44','50','93') OR observation IN ('cheque_returned','cheque_pending_clearance','operational_down_reported')) FOR UPDATE",[$issuer,$row['scope_key'],$row['remote_id'],$row['control_reference'],$eventId])->result_array();if($adverse)throw new \DomainException('bb_event_adverse_history_requires_review');
        foreach(\IssuerStorage::query($db,"SELECT n.projection_json FROM {$p}bb_api_notifications n JOIN {$p}bb_origins o ON o.id=n.origin_id AND o.issuer_id=n.issuer_id WHERE n.issuer_id=? AND o.account_id=? AND o.environment=? AND o.agreement_number=? AND o.remote_id IN (?,?) FOR UPDATE",[$issuer,$origin['account_id'],$origin['environment'],$origin['agreement_number'],$origin['remote_id'],'000'.$origin['remote_id']])->result_array() as $notification){$observed=json_decode($notification['projection_json'],true,32,JSON_THROW_ON_ERROR);if(($observed['codigoEstadoBaixaOperacional']??null)==='10')throw new \DomainException('bb_event_adverse_history_requires_review');}ApiMovements::assertNoAdverseHistory($db,$p,$origin,false);
        if($this->hasAsaas&&\IssuerStorage::query($db,"SELECT id FROM {$p}asaas_payment_origins WHERE invoice_id=? FOR UPDATE",[$invoice])->row_array())throw new \DomainException('bb_event_multiple_providers_require_review');if(\IssuerStorage::query($db,"SELECT r.payment_id FROM {$p}bb_api_receipts r JOIN {$p}bb_origins o ON o.id=r.origin_id WHERE r.issuer_id=? AND o.account_id=? AND o.environment=? AND o.agreement_number=? AND o.remote_id IN (?,?) FOR UPDATE",[$issuer,$origin['account_id'],$origin['environment'],$origin['agreement_number'],$origin['remote_id'],'000'.$origin['remote_id']])->row_array())throw new \DomainException('bb_event_credit_already_recorded_api');
        $scopeHash=hash('sha256',json_encode(['bb-external-reversal-scope',$issuer,$origin['account_id'],$origin['environment'],$origin['agreement_number']],JSON_THROW_ON_ERROR));$today=(new \DateTimeImmutable('now',new \DateTimeZone('America/Sao_Paulo')))->format('Y-m-d');$reversal=\CompanyBankReversalData::declare($original,$receipt['canonical_key'],$scopeHash,$receipt['date'],$today,$this->input);$key=hash('sha256',json_encode(['bb-full-external-reversal',$issuer,$this->paymentId,$receipt['canonical_key']],JSON_THROW_ON_ERROR));
        $this->captured=compact('issuer','actor','invoice','eventId','origin','key','reversal');return ['invoice'=>$invoice,'payment'=>$this->paymentId,'key'=>$key,'original'=>$original,'reversal'=>$reversal];
    }
    public function applied($db,string $p,int $issuer,int $actor,string $reversalKey):void
    {
        $c=$this->captured;if(!$c||$c['issuer']!==$issuer||$c['actor']!==$actor||$c['key']!==$reversalKey)throw new \DomainException('bb_external_reversal_claim_required');\IssuerTransaction::assertOwned($db,$p,$this->tables());Reconciliation::authorize($db,$p,$issuer,$actor,'external_reverse');$recorded=(new \CompanyBankReceiptReversals($db,$p))->capturedInOwned($issuer,$actor,$c['invoice'],$this->paymentId);if(!$recorded||!hash_equals($recorded->fingerprint(),$c['reversal']->fingerprint()))throw new \RuntimeException('issuer_bb_external_reversal_unconfirmed');$data=$recorded->data();Reconciliation::appendReview($db,$p,$issuer,$actor,$c['eventId'],'external_reversal_declared',$data['reason'],$data['external_reference']);Reconciliation::audit($db,$p,$issuer,(int)$c['origin']['connection_id'],$actor,'external_reversal_recorded',$c['eventId']);
    }
}
